        let t: u32 = n / 10;
        let o: u32 = n % 10;
        // Since n <= 99, t is in 1..=9 and o in 0..=9.
        let tens = (('0' as u8) + (t as u8)) as char;
        let ones = (('0' as u8) + (o as u8)) as char;
